pub struct Solution;

impl Solution {
    #[allow(clippy::ptr_arg)]
    pub fn remove_duplicates(nums: &mut Vec<i32>) -> i32 {
        if nums.is_empty() {
            return 0;
        }
        let mut insert_pos = 1;
        for i in 1..nums.len() {
            if nums[i] != nums[insert_pos - 1] {
                nums[insert_pos] = nums[i];
                insert_pos += 1;
            }
        }
        insert_pos as i32
    }
}

